    // authority (offset 8..40)
    data[8..40].copy_from_slice(&authority.to_bytes());
    // balance (offset 40..48)
    data[40..48].copy_from_slice(&500u64.to_le_bytes());
    // is_active (offset 48)
    data[48] = 1;
    data
};
let fake_treasury = account(&env.program_id, &fake_treasury_data, None);

let process_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (treasury_key, fake_treasury),
    (authority, wallet(1_000_000_000)),
];
let attack_result = env.attack("process with fake treasury", &process_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    env.effect(
        "process succeeded on account with wrong discriminator",
        true,
    );
}"
